const r = await api.get("/mails", { label: "complaint" });
const items = r.items || [];
const out = [];
for (const m of items) {
  let cust = null;
  if (m.customer_id) {
    try { cust = await api.get(`/customers/${m.customer_id}`); } catch (e) { cust = { error: String(e) }; }
  }
  out.push({ mail_id: m.id, from: m.from_name, from_email: m.from_email, customer_id: m.customer_id, contact_id: m.contact_id, subject: m.subject, customer_name: cust?.name ?? null, tier: cust?.tier ?? null });
}
return { count: r.count, out };

